class Solution{public:int shortestPathLength(vector<vector<int>>&g){int n=g.size(),T=(1<<n)-1;queue<pair<int,int>>q;vector<vector<int>>v(n,vector<int>(1<<n));for(int i=0;i<n;i++)q.push({i,1<<i}),v[i][1<<i]=1;int d=0;while(!q.empty()){for(int z=q.size();z--;){auto[u,m]=q.front();q.pop();if(m==T)return d;for(int x:g[u]){int nm=m|1<<x;if(!v[x][nm])v[x][nm]=1,q.push({x,nm});}}d++;}return 0;}};
